functions.body:
block([row, A, pivots],
    row:1,
    pivots: sort(pivots_cols),
    A:zeromatrix(m,n),
    for i thru length(pivots) do(
        piv: pivots[i],
        A[row][piv]:1,
        for j:piv+1 thru n do (
            A[row][j]:rand_with_prohib(min_val,max_val,[])
            ),
        row:row+1
        ),
     for i thru length(pivots) do(
        piv: pivots[i],
        for j:1 thru i-1 do (
            A[j][piv]:0
            )
        ),
    A)

prts.feedbackvariables:
correctVecs: false;
if hasSol=false then correctVecs:true;
if hasSol=true then if is(equal(A.ans2,b)) and is(zeromatrixp(A.ans3)) and  is(zeromatrixp(A.ans4)) and rank(addcol(ans3,ans4))=nullity then correctVecs:true;
